'use strict';

const INVOKE_FUNCTION_URL_ACTION = 'lambda:InvokeFunctionUrl';
const INVOKE_FUNCTION_ACTION = 'lambda:InvokeFunction';

/**
 * For every AWS::Lambda::Permission with Action 'lambda:InvokeFunctionUrl' generated by
 * Serverless Framework (function URLs), it adds a twin permission with Action 'lambda:InvokeFunction'.
 * The twin is scoped with InvokedViaFunctionUrl: true so it only applies when the function is invoked
 * through its function URL. The FunctionUrlAuthType property is dropped since it's specific to InvokeFunctionUrl.
 */
class ServerlessPluginAddInvokeFunctionPermissions {

	constructor(serverless) {

		this.serverless = serverless;

		this.hooks = {
			'after:aws:package:finalize:mergeCustomProviderResources': this.addInvokeFunctionPermissions.bind(this)
		};
	}

	addInvokeFunctionPermissions() {

		const template = this.serverless.service.provider.compiledCloudFormationTemplate;

		if(!template || !template.Resources)
			return;

		const addedResources = [];

		Object.entries(template.Resources).forEach(([resourceName, resource]) => {

			if(resource?.Type !== 'AWS::Lambda::Permission' || resource.Properties?.Action !== INVOKE_FUNCTION_URL_ACTION)
				return;

			const invokeFunctionResourceName = `${resourceName}InvokeFunction`;

			if(template.Resources[invokeFunctionResourceName])
				return;

			const { FunctionUrlAuthType, ...properties } = resource.Properties;

			template.Resources[invokeFunctionResourceName] = {
				...resource,
				Properties: {
					...properties,
					Action: INVOKE_FUNCTION_ACTION,
					InvokedViaFunctionUrl: true
				}
			};

			addedResources.push(invokeFunctionResourceName);
		});

		if(addedResources.length)
			this.serverless.cli.log(`${addedResources.length} lambda:InvokeFunction permissions added: [${addedResources.join(', ')}]`);
	}
}

module.exports = ServerlessPluginAddInvokeFunctionPermissions;
